BEGIN TRANSACTION;
CREATE TABLE families(id TEXT PRIMARY KEY,name TEXT NOT NULL,question TEXT NOT NULL);
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE profiles(id TEXT PRIMARY KEY,name TEXT NOT NULL,family TEXT NOT NULL REFERENCES families(id),kind TEXT NOT NULL,evidence_basis TEXT NOT NULL,mechanism TEXT NOT NULL,evidence TEXT NOT NULL,limitations TEXT NOT NULL,textdata_use TEXT NOT NULL,textdata_evaluation TEXT NOT NULL,primary_url TEXT NOT NULL,source_version TEXT NOT NULL,record_json TEXT NOT NULL);
CREATE TABLE repositories(profile_id TEXT NOT NULL REFERENCES profiles(id),url TEXT NOT NULL,inspection_scope TEXT,PRIMARY KEY(profile_id,url));
CREATE TABLE source_references(id INTEGER PRIMARY KEY,profile_id TEXT NOT NULL REFERENCES profiles(id),url TEXT NOT NULL,version TEXT,locator TEXT,observed_at TEXT);
COMMIT;
