INSERT INTO "families" VALUES('action','Action and planning','How should an agent choose, execute and revise its next step?');
INSERT INTO "families" VALUES('orchestration','Orchestration and reuse','Which responsibilities belong in program structure, and which in a model decision?');
INSERT INTO "families" VALUES('state','State and context','What must persist, and what does the model need to see now?');
INSERT INTO "families" VALUES('interfaces','Tools and skills','How should capabilities and methodological instructions be exposed?');
INSERT INTO "families" VALUES('coordination','Delegation and handoff','When does dividing work help, and what must pass between workers?');
INSERT INTO "families" VALUES('evaluation','Evaluation and adaptation','How will we assess a change without confusing extra computation with better design?');
INSERT INTO "families" VALUES('evidence','Evidence and authority','How can we recover the basis of a claim and keep source content within its proper role?');
INSERT INTO "metadata" VALUES('schema_version','2.0');
INSERT INTO "metadata" VALUES('title','TextData — Agent Design and Orchestration Database');
INSERT INTO "metadata" VALUES('as_of','2026-10-29');
INSERT INTO "metadata" VALUES('description','A database of papers, repositories, specifications and reusable components for agent design and orchestration.');
INSERT INTO "metadata" VALUES('scope','34 entries organized into seven categories. Entries describe mechanisms, supporting evidence, limitations and possible uses in TextData. Inclusion does not imply endorsement or evaluated TextData performance.');
INSERT INTO "metadata" VALUES('attribution','Original authors and maintainers are credited through each entry and its linked references.');
INSERT INTO "profiles" VALUES('AD-001','CoALA','action','Conceptual paper','Selected primary text','Organizes language agents through memory, available actions and decision cycles.','A conceptual framework relates cognitive architectures to language agents and classifies existing systems.','The taxonomy organizes mechanisms; it does not test TextData or prescribe its four-element vocabulary.','Describe what a configured research agent can read, decide and change.','Can researchers recover the agent’s inputs, available actions and reasons for consequential transitions?','https://arxiv.org/html/2309.02427v3','2024, arXiv v3','{"credit":"Sumers, Yao, Narasimhan and Griffiths (2024).","evidence":"A conceptual framework relates cognitive architectures to language agents and classifies existing systems.","evidence_basis":"Selected primary text","family":"action","id":"AD-001","implementation_status":"Not executed or benchmarked for this database.","kind":"Conceptual paper","limitations":"The taxonomy organizes mechanisms; it does not test TextData or prescribe its four-element vocabulary.","mechanism":"Organizes language agents through memory, available actions and decision cycles.","name":"CoALA","primary_locator":"§§4.1–4.6; Figs. 4–5","primary_url":"https://arxiv.org/html/2309.02427v3","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"§§4.1–4.6; Figs. 4–5","observed_at":"2026-10-29","url":"https://arxiv.org/html/2309.02427v3","version":"2024, arXiv v3"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/ysymyth/awesome-language-agents"],"source_version":"2024, arXiv v3","textdata_evaluation":"Can researchers recover the agent’s inputs, available actions and reasons for consequential transitions?","textdata_use":"Describe what a configured research agent can read, decide and change."}');
INSERT INTO "profiles" VALUES('AD-002','Building effective agents','orchestration','Engineering account','Selected primary text','Distinguishes predefined execution paths from model-directed steps; describes routing, parallelization and orchestrator–worker patterns.','First-party engineering guidance illustrates recurring arrangements.','Its narrow engineering use of workflow differs from TextData’s methodological use. It is not a controlled comparison of all patterns.','Select the simplest execution arrangement appropriate to a method and task.','Does added delegation improve the research output enough to justify its coordination cost?','https://www.anthropic.com/research/building-effective-agents','2024 article, mutable current page','{"credit":"Erik Schluntz and Barry Zhang, Anthropic (2024).","evidence":"First-party engineering guidance illustrates recurring arrangements.","evidence_basis":"Selected primary text","family":"orchestration","id":"AD-002","implementation_status":"Not executed or benchmarked for this database.","kind":"Engineering account","limitations":"Its narrow engineering use of workflow differs from TextData’s methodological use. It is not a controlled comparison of all patterns.","mechanism":"Distinguishes predefined execution paths from model-directed steps; describes routing, parallelization and orchestrator–worker patterns.","name":"Building effective agents","primary_locator":"What are agents?; Orchestrator-workers; Agents","primary_url":"https://www.anthropic.com/research/building-effective-agents","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"What are agents?; Orchestrator-workers; Agents","observed_at":"2026-10-29","url":"https://www.anthropic.com/research/building-effective-agents","version":"2024 article, mutable current page"},{"locator":"https://www.anthropic.com/engineering/building-effective-agents What are agents; Building blocks; Agents; Appendix 2","observed_at":"2026-09-20T17:51:32.240461+00:00","url":"https://www.anthropic.com/engineering/building-effective-agents","version":"Published2024-12-19; mutable body observed2026-09-20 with newer SDK/Haiku4.5/ManagedAgents note; exact update date unknown"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"2024 article, mutable current page","textdata_evaluation":"Does added delegation improve the research output enough to justify its coordination cost?","textdata_use":"Select the simplest execution arrangement appropriate to a method and task."}');
INSERT INTO "profiles" VALUES('AD-003','ReAct','action','Paper and repository','Selected primary text','Interleaves model reasoning, tool actions and observations from the environment.','The paper demonstrates the mechanism on question answering and interactive tasks.','Task and model results do not establish the validity of an organizational interpretation; prompts and feedback affect behavior.','Let an agent request a source passage or calculation, inspect the returned evidence and revise its next step.','Does a claim actually change when a retrieved passage contradicts the initial interpretation?','https://arxiv.org/html/2210.03629v3','2023, arXiv v3','{"credit":"Yao et al. (2023).","evidence":"The paper demonstrates the mechanism on question answering and interactive tasks.","evidence_basis":"Selected primary text","family":"action","id":"AD-003","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"Task and model results do not establish the validity of an organizational interpretation; prompts and feedback affect behavior.","mechanism":"Interleaves model reasoning, tool actions and observations from the environment.","name":"ReAct","primary_locator":"§2; §3.1 Action Space; §3.2; Appendix A.3","primary_url":"https://arxiv.org/html/2210.03629v3","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"§2; §3.1 Action Space; §3.2; Appendix A.3","observed_at":"2026-10-29","url":"https://arxiv.org/html/2210.03629v3","version":"2023, arXiv v3"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/ysymyth/ReAct"],"source_version":"2023, arXiv v3","textdata_evaluation":"Does a claim actually change when a retrieved passage contradicts the initial interpretation?","textdata_use":"Let an agent request a source passage or calculation, inspect the returned evidence and revise its next step."}');
INSERT INTO "profiles" VALUES('AD-004','AutoGen','coordination','Paper and repository','Selected primary text','Configurable agents exchange messages under programmable conversation and termination rules.','The inspected paper combines language models, tools and human inputs in several applications.','The 2023 paper manifestation is distinct from later software APIs. Agent roles alone do not establish expertise, independent errors or successful collaboration.','Specify the evidence, work product and completion condition expected from each delegated role.','Compare the same research task with one agent and with explicitly partitioned work, accounting for calls and context.','https://arxiv.org/html/2308.08155v2','2023 preprint v2; 2024 COLM publication identity','{"credit":"Wu et al. (2024); inspected arXiv v2 (2023).","evidence":"The inspected paper combines language models, tools and human inputs in several applications.","evidence_basis":"Selected primary text","family":"coordination","id":"AD-004","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"The 2023 paper manifestation is distinct from later software APIs. Agent roles alone do not establish expertise, independent errors or successful collaboration.","mechanism":"Configurable agents exchange messages under programmable conversation and termination rules.","name":"AutoGen","primary_locator":"§§2.1–2.2","primary_url":"https://arxiv.org/html/2308.08155v2","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"§§2.1–2.2","observed_at":"2026-10-29","url":"https://arxiv.org/html/2308.08155v2","version":"2023 preprint v2; 2024 COLM publication identity"},{"locator":null,"observed_at":null,"url":"https://openreview.net/forum?id=BAakY1hNKS","version":"COLM2024 venue metadata; title uses Conversations"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/microsoft/autogen"],"source_version":"2023 preprint v2; 2024 COLM publication identity","textdata_evaluation":"Compare the same research task with one agent and with explicitly partitioned work, accounting for calls and context.","textdata_use":"Specify the evidence, work product and completion condition expected from each delegated role."}');
INSERT INTO "profiles" VALUES('AD-005','DSPy','orchestration','Paper and repository','Selected primary text','Separates declared input/output interfaces and modular programs from prompts optimized against a metric.','The paper evaluates compilation of language-model programs on specified question-answering and reasoning tasks.','Optimization is tied to data, model and metric. Interface reuse does not guarantee stable scientific meaning after a model change.','Keep a construct specification separate from the prompt implementation used to extract or classify evidence.','Compare unchanged reuse, renewed optimization and a manual baseline on held-out materials.','https://arxiv.org/html/2310.03714v1','2023 preprint v1; 2024 ICLR publication identity','{"credit":"Khattab et al. (2024); inspected 2023 arXiv manifestation.","evidence":"The paper evaluates compilation of language-model programs on specified question-answering and reasoning tasks.","evidence_basis":"Selected primary text","family":"orchestration","id":"AD-005","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"Optimization is tied to data, model and metric. Interface reuse does not guarantee stable scientific meaning after a model change.","mechanism":"Separates declared input/output interfaces and modular programs from prompts optimized against a metric.","name":"DSPy","primary_locator":"§§3.1–3.3; §4","primary_url":"https://arxiv.org/html/2310.03714v1","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"§§3.1–3.3; §4","observed_at":"2026-10-29","url":"https://arxiv.org/html/2310.03714v1","version":"2023 preprint v1; 2024 ICLR publication identity"},{"locator":"https://openreview.net/notes/edits/attachment?id=wU1R77dqOm&name=pdf ; pp1,6–9,14","observed_at":null,"url":"https://openreview.net/notes/edits/attachment?id=wU1R77dqOm&name=pdf","version":"ICLR2024"},{"locator":"https://github.com/stanfordnlp/dspy/releases ; 3.4.0 Beta1 compatibility and migration;3.3.1","observed_at":null,"url":"https://github.com/stanfordnlp/dspy/releases","version":"3.3.1 / 3.4.0b1"},{"locator":"https://github.com/stanfordnlp/dspy/blob/main/docs/docs/tutorials/saving/index.md ; State-only, Whole Program, Backward Compatibility","observed_at":null,"url":"https://github.com/stanfordnlp/dspy/blob/main/docs/docs/tutorials/saving/index.md","version":"mutable main"},{"locator":"https://github.com/stanfordnlp/dspy/blob/main/docs/docs/learn/optimization/optimizers.md ; What an optimizer tunes;Which optimizer","observed_at":null,"url":"https://github.com/stanfordnlp/dspy/blob/main/docs/docs/learn/optimization/optimizers.md","version":"mutable main"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/stanfordnlp/dspy"],"source_version":"2023 preprint v1; 2024 ICLR publication identity","textdata_evaluation":"Compare unchanged reuse, renewed optimization and a manual baseline on held-out materials.","textdata_use":"Keep a construct specification separate from the prompt implementation used to extract or classify evidence."}');
INSERT INTO "profiles" VALUES('AD-006','Model Context Protocol resources and tools','interfaces','Specification','Selected primary text','Resources expose contextual data; tools expose callable operations through a shared protocol.','The current resource specification explicitly describes contextual data and application-controlled presentation.','Protocol compatibility does not establish source validity, permission to act, transactional effects or implementation equivalence.','Expose source collections and analytic operations as distinct interfaces without conflating them with study design.','Can a tool call be traced to its input source and study-specific assumptions?','https://modelcontextprotocol.io/specification/2026-07-28/server/resources','2026-07-28 specification; 2025-06-18 historical comparison','{"credit":"Model Context Protocol contributors.","evidence":"The current resource specification explicitly describes contextual data and application-controlled presentation.","evidence_basis":"Selected primary text","family":"interfaces","id":"AD-006","implementation_status":"Not executed or benchmarked for this database.","kind":"Specification","limitations":"Protocol compatibility does not establish source validity, permission to act, transactional effects or implementation equivalence.","mechanism":"Resources expose contextual data; tools expose callable operations through a shared protocol.","name":"Model Context Protocol resources and tools","primary_locator":"Resources and Tools: introductions and user interaction models","primary_url":"https://modelcontextprotocol.io/specification/2026-07-28/server/resources","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"Resources and Tools: introductions and user interaction models","observed_at":"2026-10-29","url":"https://modelcontextprotocol.io/specification/2026-07-28/server/resources","version":"2026-07-28 specification; 2025-06-18 historical comparison"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/modelcontextprotocol/specification"],"source_version":"2026-07-28 specification; 2025-06-18 historical comparison","textdata_evaluation":"Can a tool call be traced to its input source and study-specific assumptions?","textdata_use":"Expose source collections and analytic operations as distinct interfaces without conflating them with study design."}');
INSERT INTO "profiles" VALUES('AD-007','Co-Scientist','coordination','Scientific system paper','Selected primary text','Converts a scientist’s goal and constraints into a plan with specialized generation, critique and refinement work.','The Nature article reports biomedical hypothesis development with expert assessment and experimental follow-up.','The demonstrations are biomedical and include human/laboratory contributions. Co-Scientist is distinct from the chemistry system Coscientist; no public implementation is inferred.','Organize a bounded research task around a question, admissible evidence and requested output.','Does coordination yield better-supported rival explanations on organizational texts?','https://www.nature.com/articles/s41586-026-10644-y','2026 published Nature article','{"credit":"Gottweis et al. (2026).","evidence":"The Nature article reports biomedical hypothesis development with expert assessment and experimental follow-up.","evidence_basis":"Selected primary text","family":"coordination","id":"AD-007","implementation_status":"Not executed or benchmarked for this database.","kind":"Scientific system paper","limitations":"The demonstrations are biomedical and include human/laboratory contributions. Co-Scientist is distinct from the chemistry system Coscientist; no public implementation is inferred.","mechanism":"Converts a scientist’s goal and constraints into a plan with specialized generation, critique and refinement work.","name":"Co-Scientist","primary_locator":"Fig. 1; Methods: From research goal to research plan configuration; The specialized agents underpinning Co-Scientist; limitations discussion","primary_url":"https://www.nature.com/articles/s41586-026-10644-y","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"Fig. 1; Methods: From research goal to research plan configuration; The specialized agents underpinning Co-Scientist; limitations discussion","observed_at":"2026-10-29","url":"https://www.nature.com/articles/s41586-026-10644-y","version":"2026 published Nature article"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"2026 published Nature article","textdata_evaluation":"Does coordination yield better-supported rival explanations on organizational texts?","textdata_use":"Organize a bounded research task around a question, admissible evidence and requested output."}');
INSERT INTO "profiles" VALUES('AD-008','Anthropic multi-agent Research','coordination','Engineering account','Selected primary text','A lead agent delegates bounded searches, receives findings and decides whether to continue.','The first-party account describes deployed design decisions and internal evaluation.','Larger resource use and internal tasks prevent isolating agent-count benefits or assuming transfer to scholarly review.','Partition independent search questions while retaining source references for synthesis.','Measure missed evidence, overlap and integration effort against a comparable single-agent search.','https://www.anthropic.com/research/multi-agent-research-system','2025-06-13, current mutable page','{"credit":"Anthropic engineering contributors (2025).","evidence":"The first-party account describes deployed design decisions and internal evaluation.","evidence_basis":"Selected primary text","family":"coordination","id":"AD-008","implementation_status":"Not executed or benchmarked for this database.","kind":"Engineering account","limitations":"Larger resource use and internal tasks prevent isolating agent-count benefits or assuming transfer to scholarly review.","mechanism":"A lead agent delegates bounded searches, receives findings and decides whether to continue.","name":"Anthropic multi-agent Research","primary_locator":"Architecture overview; delegation principle 2; Benefits; Effective evaluation","primary_url":"https://www.anthropic.com/research/multi-agent-research-system","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"Architecture overview; delegation principle 2; Benefits; Effective evaluation","observed_at":"2026-10-29","url":"https://www.anthropic.com/research/multi-agent-research-system","version":"2025-06-13, current mutable page"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"2025-06-13, current mutable page","textdata_evaluation":"Measure missed evidence, overlap and integration effort against a comparable single-agent search.","textdata_use":"Partition independent search questions while retaining source references for synthesis."}');
INSERT INTO "profiles" VALUES('AD-009','Effective context engineering','state','Engineering account','Selected primary text','Uses references, selective retrieval and compaction to manage what a model sees during long tasks.','First-party guidance explains context selection and long-horizon working practices.','Compaction can omit distinctions; smaller context is not necessarily more faithful context.','Load relevant passages and method guidance while retaining separately addressable originals.','Test whether a resumed analysis retains contrary evidence and consequential study commitments.','https://www.anthropic.com/research/effective-context-engineering-for-ai-agents','2025-09-29, current mutable page','{"credit":"Anthropic engineering contributors (2025).","evidence":"First-party guidance explains context selection and long-horizon working practices.","evidence_basis":"Selected primary text","family":"state","id":"AD-009","implementation_status":"Not executed or benchmarked for this database.","kind":"Engineering account","limitations":"Compaction can omit distinctions; smaller context is not necessarily more faithful context.","mechanism":"Uses references, selective retrieval and compaction to manage what a model sees during long tasks.","name":"Effective context engineering","primary_locator":"Context retrieval and agentic search; long-horizon context/compaction","primary_url":"https://www.anthropic.com/research/effective-context-engineering-for-ai-agents","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"Context retrieval and agentic search; long-horizon context/compaction","observed_at":"2026-10-29","url":"https://www.anthropic.com/research/effective-context-engineering-for-ai-agents","version":"2025-09-29, current mutable page"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"2025-09-29, current mutable page","textdata_evaluation":"Test whether a resumed analysis retains contrary evidence and consequential study commitments.","textdata_use":"Load relevant passages and method guidance while retaining separately addressable originals."}');
INSERT INTO "profiles" VALUES('AD-010','LLooM','evidence','Paper and repository','Selected primary text','Supports concept induction with analyst inspection, editing and re-analysis.','The paper combines concept-level evaluations with exploratory expert cases.','The authors identify overreliance and bias risks. Concept scores and editable concepts do not by themselves validate an organizational explanation.','Keep generated concepts open to source inspection and researcher revision.','Do analysts detect missed concepts and unsupported distinctions, including alternatives outside the generated set?','https://arxiv.org/html/2404.12259v1','2024, CHI article / arXiv v1','{"credit":"Lam, Teoh, Landay, Heer and Bernstein (2024).","evidence":"The paper combines concept-level evaluations with exploratory expert cases.","evidence_basis":"Selected primary text","family":"evidence","id":"AD-010","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"The authors identify overreliance and bias risks. Concept scores and editable concepts do not by themselves validate an organizational explanation.","mechanism":"Supports concept induction with analyst inspection, editing and re-analysis.","name":"LLooM","primary_locator":"§3.2.2; §6 opening and scope; §7.2.3","primary_url":"https://arxiv.org/html/2404.12259v1","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"§3.2.2; §6 opening and scope; §7.2.3","observed_at":"2026-10-29","url":"https://arxiv.org/html/2404.12259v1","version":"2024, CHI article / arXiv v1"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/stanfordhci/lloom"],"source_version":"2024, CHI article / arXiv v1","textdata_evaluation":"Do analysts detect missed concepts and unsupported distinctions, including alternatives outside the generated set?","textdata_use":"Keep generated concepts open to source inspection and researcher revision."}');
INSERT INTO "profiles" VALUES('AD-011','MAST','coordination','Failure-analysis paper','Selected primary text','Classifies system-design, inter-agent alignment and task-verification failures.','The primary paper supplies failure categories and selected intervention studies.','The identities and correspondence of released traces and annotations remain unresolved in the documented evidence. Use the taxonomy provisionally; dataset counts should not be treated as independent observations or as a universal failure rate.','Inspect whether failures arise in the task specification, handoff or assessment of completion.','Can the failure classification distinguish missing evidence from incorrect synthesis and premature stopping?','https://arxiv.org/html/2503.13657v3','2025, arXiv v3; NeurIPS proceedings identity','{"credit":"Cemri et al. (2025).","evidence":"The primary paper supplies failure categories and selected intervention studies.","evidence_basis":"Selected primary text","family":"coordination","id":"AD-011","implementation_status":"Not executed or benchmarked for this database.","kind":"Failure-analysis paper","limitations":"The identities and correspondence of released traces and annotations remain unresolved in the documented evidence. Use the taxonomy provisionally; dataset counts should not be treated as independent observations or as a universal failure rate.","mechanism":"Classifies system-design, inter-agent alignment and task-verification failures.","name":"MAST","primary_locator":"§§3–5; Appendix A failure categories","primary_url":"https://arxiv.org/html/2503.13657v3","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"§§3–5; Appendix A failure categories","observed_at":"2026-10-29","url":"https://arxiv.org/html/2503.13657v3","version":"2025, arXiv v3; NeurIPS proceedings identity"},{"locator":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/13 Description / reproduction / qualification","observed_at":null,"url":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/13","version":"2026-05-06"},{"locator":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/18 Description / reproduction / qualification","observed_at":null,"url":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/18","version":"2026-08-23"},{"locator":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/17 Description / reproduction / qualification","observed_at":null,"url":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/17","version":"2026-08-09"},{"locator":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/16 Description / reproduction / qualification","observed_at":null,"url":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/16","version":"2026-08-07"},{"locator":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/12 Description / reproduction / qualification","observed_at":null,"url":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/12","version":"2026-05-06"},{"locator":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/10 Description / reproduction and limitations","observed_at":null,"url":"https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/10","version":"2025-10-30 issue; mutable"},{"locator":"https://huggingface.co/datasets/mcemri/MAST-Data/commit/95118ac951421753cf1deb87ddea3b01e693c41b; dataset commit metadata and pinned README, Notes","observed_at":"2026-09-21T02:55:22.055473+00:00","url":"https://huggingface.co/datasets/mcemri/MAST-Data/commit/95118ac951421753cf1deb87ddea3b01e693c41b","version":"95118ac951421753cf1deb87ddea3b01e693c41b at2026-08-13T19:46:12Z; prior6bd601d98498910e079b4fd0a7a6d4c0ab3cae60 at19:38:25Z"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/multi-agent-systems-failure-taxonomy/MAST"],"source_version":"2025, arXiv v3; NeurIPS proceedings identity","textdata_evaluation":"Can the failure classification distinguish missing evidence from incorrect synthesis and premature stopping?","textdata_use":"Inspect whether failures arise in the task specification, handoff or assessment of completion."}');
INSERT INTO "profiles" VALUES('AD-012','W3C PROV-DM','evidence','Specification','Selected primary text','Represents entities, activities, derivation and responsibility.','A domain-independent provenance model specifies how outputs relate to inputs and activities.','Provenance describes derivation, not truth. A PROV agent can be a responsible person or system and is not synonymous with an LLM agent.','Connect source passages, derived codes, memos and claims without treating their derivation as validation.','Can a reader trace an interpretation to the source version and decision that produced it?','https://www.w3.org/TR/2013/REC-prov-dm-20130430/','W3C Recommendation 2013-04-30','{"credit":"Moreau, Missier and W3C Provenance Working Group (2013).","evidence":"A domain-independent provenance model specifies how outputs relate to inputs and activities.","evidence_basis":"Selected primary text","family":"evidence","id":"AD-012","implementation_status":"Not executed or benchmarked for this database.","kind":"Specification","limitations":"Provenance describes derivation, not truth. A PROV agent can be a responsible person or system and is not synonymous with an LLM agent.","mechanism":"Represents entities, activities, derivation and responsibility.","name":"W3C PROV-DM","primary_locator":"§§2.1, 2.2.2, 4, 5.2–5.3","primary_url":"https://www.w3.org/TR/2013/REC-prov-dm-20130430/","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"§§2.1, 2.2.2, 4, 5.2–5.3","observed_at":"2026-10-29","url":"https://www.w3.org/TR/2013/REC-prov-dm-20130430/","version":"W3C Recommendation 2013-04-30"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"W3C Recommendation 2013-04-30","textdata_evaluation":"Can a reader trace an interpretation to the source version and decision that produced it?","textdata_use":"Connect source passages, derived codes, memos and claims without treating their derivation as validation."}');
INSERT INTO "profiles" VALUES('AD-013','Managed Agents architecture','state','Engineering account','Selected primary text','Separates the durable session event log, the agent execution loop and the sandbox.','The April 2026 engineering account explains these interfaces and how the current model context is assembled.','A vendor architecture account is not independent evidence of TextData reliability. A durable log does not guarantee complete or correct model context.','Retain study records outside a replaceable agent session while making the current context inspectable.','After replacing a model or worker, can the inquiry resume with its evidence and unresolved decisions intact?','https://www.anthropic.com/research/managed-agents','2026-04-08, current mutable page','{"credit":"Anthropic engineering contributors (2026).","evidence":"The April 2026 engineering account explains these interfaces and how the current model context is assembled.","evidence_basis":"Selected primary text","family":"state","id":"AD-013","implementation_status":"Not executed or benchmarked for this database.","kind":"Engineering account","limitations":"A vendor architecture account is not independent evidence of TextData reliability. A durable log does not guarantee complete or correct model context.","mechanism":"Separates the durable session event log, the agent execution loop and the sandbox.","name":"Managed Agents architecture","primary_locator":"The session is not Claude’s context window; stable interfaces","primary_url":"https://www.anthropic.com/research/managed-agents","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"The session is not Claude’s context window; stable interfaces","observed_at":"2026-10-29","url":"https://www.anthropic.com/research/managed-agents","version":"2026-04-08, current mutable page"},{"locator":"https://www.anthropic.com/engineering/managed-agents ; Decoupling architecture","observed_at":null,"url":"https://www.anthropic.com/engineering/managed-agents","version":"2026-04-08"},{"locator":"https://platform.claude.com/docs/en/managed-agents/overview ; Core concepts;Beta access","observed_at":null,"url":"https://platform.claude.com/docs/en/managed-agents/overview","version":"beta header2026-04-01"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"2026-04-08, current mutable page","textdata_evaluation":"After replacing a model or worker, can the inquiry resume with its evidence and unresolved decisions intact?","textdata_use":"Retain study records outside a replaceable agent session while making the current context inspectable."}');
INSERT INTO "profiles" VALUES('AD-014','LangGraph persistence','state','Repository and documentation','Selected primary text','Separates thread-state checkpoints from cross-thread application data stored in a store.','Official documentation distinguishes the two interfaces and warns that in-memory savers do not survive process restart.','Restart durability depends on the backing store and configuration. Checkpoints do not make arbitrary external effects atomic or establish analysis validity.','Keep execution position separate from the enduring study evidence and decisions.','Interrupt a task and check both correct resumption and absence of duplicated external effects.','https://docs.langchain.com/oss/python/langgraph/persistence','current documentation, accessed 2026-10-29','{"credit":"Original authors and maintainers are identified in the linked publication or repository.","evidence":"Official documentation distinguishes the two interfaces and warns that in-memory savers do not survive process restart.","evidence_basis":"Selected primary text","family":"state","id":"AD-014","implementation_status":"Not executed or benchmarked for this database.","kind":"Repository and documentation","limitations":"Restart durability depends on the backing store and configuration. Checkpoints do not make arbitrary external effects atomic or establish analysis validity.","mechanism":"Separates thread-state checkpoints from cross-thread application data stored in a store.","name":"LangGraph persistence","primary_locator":"Overview; Checkpointer vs. store","primary_url":"https://docs.langchain.com/oss/python/langgraph/persistence","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"Overview; Checkpointer vs. store","observed_at":"2026-10-29","url":"https://docs.langchain.com/oss/python/langgraph/persistence","version":"current documentation, accessed 2026-10-29"},{"locator":null,"observed_at":null,"url":"https://github.com/langchain-ai/langgraph/releases/tag/1.2.11","version":"1.2.11"},{"locator":"https://docs.langchain.com/oss/python/langgraph/graph-api ; Graph migrations","observed_at":null,"url":"https://docs.langchain.com/oss/python/langgraph/graph-api","version":"mutable docs"},{"locator":"https://github.com/langchain-ai/langgraph/issues/8834 ; Repro;Observed output;Environment","observed_at":null,"url":"https://github.com/langchain-ai/langgraph/issues/8834","version":"Sep6,2026"},{"locator":"https://github.com/langchain-ai/langgraph/issues/8833 ; Observed output,System Info","observed_at":null,"url":"https://github.com/langchain-ai/langgraph/issues/8833","version":"Sep2026;SQLite3.1.1"},{"locator":"https://github.com/langchain-ai/langgraph/security/advisories/GHSA-9rwj-6rc7-p77c ; Affected/Patched versions","observed_at":null,"url":"https://github.com/langchain-ai/langgraph/security/advisories/GHSA-9rwj-6rc7-p77c","version":"Dec9,2025 advisory"},{"locator":"https://github.com/langchain-ai/langgraph/issues/7417 ; issue body","observed_at":null,"url":"https://github.com/langchain-ai/langgraph/issues/7417","version":"1.1.3–1.1.6;langgraph-api0.7.28/0.7.96;Apr5,2026"},{"locator":"https://github.com/langchain-ai/langgraph/issues/8458 ; issue body","observed_at":null,"url":"https://github.com/langchain-ai/langgraph/issues/8458","version":"1.1.7 through1.2.9;Jul27,2026"},{"locator":"https://github.com/langchain-ai/langgraph/issues/8579 ; issue body","observed_at":null,"url":"https://github.com/langchain-ai/langgraph/issues/8579","version":"Aug9,2026 main version not pinned"},{"locator":"https://research.checkpoint.com/2026/from-sqli-to-rce-exploiting-langgraphs-checkpointer/ ; Key Points / Disclosure Timeline","observed_at":null,"url":"https://research.checkpoint.com/2026/from-sqli-to-rce-exploiting-langgraphs-checkpointer/","version":"June11,2026"},{"locator":"https://docs.langchain.com/oss/python/langgraph/checkpointers ; Checkpoints / pending writes / Durability modes","observed_at":"2026-09-20T19:40:58.232Z","url":"https://docs.langchain.com/oss/python/langgraph/checkpointers","version":"Mutable documentation; observed 20 September 2026."}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/langchain-ai/langgraph"],"source_version":"current documentation, accessed 2026-10-29","textdata_evaluation":"Interrupt a task and check both correct resumption and absence of duplicated external effects.","textdata_use":"Keep execution position separate from the enduring study evidence and decisions."}');
INSERT INTO "profiles" VALUES('AD-015','Reflexion','action','Paper and repository','Documented source summary','Stores verbal feedback from prior attempts and uses it to guide a later attempt without updating model weights.','The paper extraction includes task improvements and harmful-reflection ablations.','Self-generated feedback can reinforce mistakes; more attempts and useful external feedback affect comparisons.','Turn a documented error into an explicit revision question while preserving the previous interpretation.','Does revision repair the identified source mismatch without introducing new unsupported claims?','https://arxiv.org/html/2303.11366v4','v4 2023-10-10','{"credit":"Shinn et al. (2023).","evidence":"The paper extraction includes task improvements and harmful-reflection ablations.","evidence_basis":"Documented source summary","family":"action","id":"AD-015","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"Self-generated feedback can reinforce mistakes; more attempts and useful external feedback affect comparisons.","mechanism":"Stores verbal feedback from prior attempts and uses it to guide a later attempt without updating model weights.","name":"Reflexion","primary_locator":"https://arxiv.org/html/2303.11366v4 Sections 3, 4.1–4.3; Table 3; Section 5","primary_url":"https://arxiv.org/html/2303.11366v4","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://arxiv.org/html/2303.11366v4 Sections 3, 4.1–4.3; Table 3; Section 5","observed_at":"2026-09-20T17:51:32.242164+00:00","url":"https://arxiv.org/html/2303.11366v4","version":"v4 2023-10-10"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/noahshinn/reflexion"],"source_version":"v4 2023-10-10","textdata_evaluation":"Does revision repair the identified source mismatch without introducing new unsupported claims?","textdata_use":"Turn a documented error into an explicit revision question while preserving the previous interpretation."}');
INSERT INTO "profiles" VALUES('AD-016','Tree of Thoughts','action','Paper and repository','Documented source summary','Searches alternative intermediate states using model-based evaluation and tree search.','The paper describes breadth-first and depth-first search on bounded reasoning tasks.','Benefits depend on useful candidate generation and evaluation, and on added computation. A coherent path need not be empirically supported.','Explore rival analytic interpretations before retaining a category or explanation.','Compare alternatives with equal-budget sampling and evaluate them against source evidence.','https://arxiv.org/html/2305.10601v2','v2 2023-12-03; NeurIPS camera ready','{"credit":"Yao et al. (2023).","evidence":"The paper describes breadth-first and depth-first search on bounded reasoning tasks.","evidence_basis":"Documented source summary","family":"action","id":"AD-016","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"Benefits depend on useful candidate generation and evaluation, and on added computation. A coherent path need not be empirically supported.","mechanism":"Searches alternative intermediate states using model-based evaluation and tree search.","name":"Tree of Thoughts","primary_locator":"https://arxiv.org/html/2305.10601v2 Section 4.1 Table 2; Section 6; Appendix B.3 Table 7","primary_url":"https://arxiv.org/html/2305.10601v2","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://arxiv.org/html/2305.10601v2 Section 4.1 Table 2; Section 6; Appendix B.3 Table 7","observed_at":"2026-09-20T17:51:32.242454+00:00","url":"https://arxiv.org/html/2305.10601v2","version":"v2 2023-12-03; NeurIPS camera ready"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/princeton-nlp/tree-of-thought-llm"],"source_version":"v2 2023-12-03; NeurIPS camera ready","textdata_evaluation":"Compare alternatives with equal-budget sampling and evaluate them against source evidence.","textdata_use":"Explore rival analytic interpretations before retaining a category or explanation."}');
INSERT INTO "profiles" VALUES('AD-017','LLMCompiler','action','Paper and repository','Selected primary text','Plans tool calls with dependencies, dispatches independent calls in parallel and can replan after observations.','The paper evaluates function-calling workloads and interactive tasks; parallelism helps where the dependency structure permits it.','Sequential interactive tasks can incur planning overhead. Reported speedups do not establish faster or better organizational research.','Parallelize independent document preparation or retrieval while preserving dependent interpretation steps.','Compare result fidelity and elapsed time with sequential execution on the same task graph.','https://arxiv.org/html/2312.04511v3','2024-06-05 v3','{"credit":"Kim et al. (2024).","evidence":"The paper evaluates function-calling workloads and interactive tasks; parallelism helps where the dependency structure permits it.","evidence_basis":"Selected primary text","family":"action","id":"AD-017","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"Sequential interactive tasks can incur planning overhead. Reported speedups do not establish faster or better organizational research.","mechanism":"Plans tool calls with dependencies, dispatches independent calls in parallel and can replan after observations.","name":"LLMCompiler","primary_locator":"§3; §5.4; Appendix B","primary_url":"https://arxiv.org/html/2312.04511v3","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"§3; §5.4; Appendix B","observed_at":"2026-10-29","url":"https://arxiv.org/html/2312.04511v3","version":"2024-06-05 v3"},{"locator":"https://arxiv.org/html/2312.04511v3 §3–4,Tables1–3,AppendixA/D","observed_at":"2026-09-20T18:49:31.746734+00:00","url":"https://arxiv.org/html/2312.04511v3","version":"2024-06-05 v3"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/SqueezeAILab/LLMCompiler"],"source_version":"2024-06-05 v3","textdata_evaluation":"Compare result fidelity and elapsed time with sequential execution on the same task graph.","textdata_use":"Parallelize independent document preparation or retrieval while preserving dependent interpretation steps."}');
INSERT INTO "profiles" VALUES('AD-018','Open Agent Specification','orchestration','Paper and repository','Documented source summary','Serializes agent and workflow definitions and connects them to runtime adapters.','The empirical paper runs related configurations across frameworks and reports differences in outputs and latency.','An older technical report deferred evaluation; the later empirical manifestation supersedes that claim. Configuration interchange does not demonstrate suspended-state migration or identical semantics.','Separate an explicit study/task specification from a particular execution framework.','Run the same specified operation across implementations and assess semantic, output and recovery differences.','https://arxiv.org/html/2510.04173v4','Empirical arXiv v4 (2025), CAIS 2026 identity; software 26.3.1 documented in September 2026.','{"credit":"Agent Spec paper authors and Oracle contributors.","evidence":"The empirical paper runs related configurations across frameworks and reports differences in outputs and latency.","evidence_basis":"Documented source summary","family":"orchestration","id":"AD-018","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"An older technical report deferred evaluation; the later empirical manifestation supersedes that claim. Configuration interchange does not demonstrate suspended-state migration or identical semantics.","mechanism":"Serializes agent and workflow definitions and connects them to runtime adapters.","name":"Open Agent Specification","primary_locator":"https://arxiv.org/html/2510.04173v4 ; §5.1–5.2 Tables3–5","primary_url":"https://arxiv.org/html/2510.04173v4","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://arxiv.org/html/2510.04173v4 ; §5.1–5.2 Tables3–5","observed_at":null,"url":"https://arxiv.org/html/2510.04173v4","version":"v4 Nov7,2025;older v1 technical report"},{"locator":"https://doi.org/10.1145/3786335.3813130 ; §2.2;§4 tool semantics;§5.1","observed_at":null,"url":"https://doi.org/10.1145/3786335.3813130","version":"CAIS2026 May26"},{"locator":"https://oracle.github.io/agent-spec/development/_downloads/9bed8c437b5139f7c816476b7e2c20f1/agentspec_technical_report.pdf ; §2.3–2.6,especially§2.6.1","observed_at":null,"url":"https://oracle.github.io/agent-spec/development/_downloads/9bed8c437b5139f7c816476b7e2c20f1/agentspec_technical_report.pdf","version":"report references25.4.0;mutable development URL"},{"locator":"https://github.com/oracle/agent-spec/releases ; 26.3.1 Dependencies,LangGraph improvements,Breaking changes","observed_at":null,"url":"https://github.com/oracle/agent-spec/releases","version":"26.3.1 Sep11,2026"},{"locator":"https://oracle.github.io/agent-spec/26.3.1/howtoguides/howto_execute_agentspec_across_frameworks.html ; Adapters;tool_registry;license comment","observed_at":null,"url":"https://oracle.github.io/agent-spec/26.3.1/howtoguides/howto_execute_agentspec_across_frameworks.html","version":"26.3.1"},{"locator":"https://github.com/oracle/agent-spec/issues/81 ; Context/Acceptance","observed_at":null,"url":"https://github.com/oracle/agent-spec/issues/81","version":"Jan20,2026;open observed"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/oracle/agent-spec"],"source_version":"Empirical arXiv v4 (2025), CAIS 2026 identity; software 26.3.1 documented in September 2026.","textdata_evaluation":"Run the same specified operation across implementations and assess semantic, output and recovery differences.","textdata_use":"Separate an explicit study/task specification from a particular execution framework."}');
INSERT INTO "profiles" VALUES('AD-019','Temporal agent integration','orchestration','Repository and documentation','Documented source summary','Runs an agent loop inside a durable workflow and records model and I/O operations as replayable activities.','The versioned integration README documents replay, session carryover and implementation restrictions.','Inspected integration 1.24.0 is experimental. Replaying recorded results does not guarantee exactly-once remote effects; continuation and approval support have explicit limits.','Explore recovery for long research operations whose dependencies and external effects are explicit.','Check interrupted writes, retries, session continuity and effects separately before relying on recovery.','https://github.com/temporalio/sdk-typescript/blob/v1.24.0/contrib/openai-agents/README.md','@temporalio/openai-agents1.24.0 experimental; npm date verified','{"credit":"Temporal contributors.","evidence":"The versioned integration README documents replay, session carryover and implementation restrictions.","evidence_basis":"Documented source summary","family":"orchestration","id":"AD-019","implementation_status":"Not executed or benchmarked for this database.","kind":"Repository and documentation","limitations":"Inspected integration 1.24.0 is experimental. Replaying recorded results does not guarantee exactly-once remote effects; continuation and approval support have explicit limits.","mechanism":"Runs an agent loop inside a durable workflow and records model and I/O operations as replayable activities.","name":"Temporal agent integration","primary_locator":"https://github.com/temporalio/sdk-typescript/blob/v1.24.0/contrib/openai-agents/README.md ; Introduction; Tools; modelParams","primary_url":"https://github.com/temporalio/sdk-typescript/blob/v1.24.0/contrib/openai-agents/README.md","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://github.com/temporalio/sdk-typescript/blob/v1.24.0/contrib/openai-agents/README.md ; Introduction; Tools; modelParams","observed_at":null,"url":"https://github.com/temporalio/sdk-typescript/blob/v1.24.0/contrib/openai-agents/README.md","version":"@temporalio/openai-agents1.24.0 experimental; npm date verified"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/temporalio/sdk-typescript"],"source_version":"@temporalio/openai-agents1.24.0 experimental; npm date verified","textdata_evaluation":"Check interrupted writes, retries, session continuity and effects separately before relying on recovery.","textdata_use":"Explore recovery for long research operations whose dependencies and external effects are explicit."}');
INSERT INTO "profiles" VALUES('AD-020','MemGPT','state','Paper and repository','Selected primary text','Moves information between limited working context and external recall/archival storage through explicit function calls.','The paper evaluates conversational memory and document analysis and describes lossy recursive summaries beside retained history.','A stored source may still be missed or poorly summarized. Historical MemGPT results are not guarantees for the current Letta product.','Keep original study materials recoverable when working summaries are compacted.','Test recovery of a rarely used contrary passage after several analysis cycles.','https://arxiv.org/html/2310.08560v2','2024-02-12 v2','{"credit":"Packer et al.; inspected 2024 arXiv v2.","evidence":"The paper evaluates conversational memory and document analysis and describes lossy recursive summaries beside retained history.","evidence_basis":"Selected primary text","family":"state","id":"AD-020","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"A stored source may still be missed or poorly summarized. Historical MemGPT results are not guarantees for the current Letta product.","mechanism":"Moves information between limited working context and external recall/archival storage through explicit function calls.","name":"MemGPT","primary_locator":"§2.1–2.4; §3","primary_url":"https://arxiv.org/html/2310.08560v2","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"§2.1–2.4; §3","observed_at":"2026-10-29","url":"https://arxiv.org/html/2310.08560v2","version":"2024-02-12 v2"},{"locator":"https://arxiv.org/html/2310.08560v2 — §2, §3.1, §3.2.1","observed_at":null,"url":"https://arxiv.org/html/2310.08560v2","version":"2024-02-12 v2"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/letta-ai/letta"],"source_version":"2024-02-12 v2","textdata_evaluation":"Test recovery of a rarely used contrary passage after several analysis cycles.","textdata_use":"Keep original study materials recoverable when working summaries are compacted."}');
INSERT INTO "profiles" VALUES('AD-021','Mem0','state','Paper and repository','Documented source summary','Extracts and retrieves persistent information; the inspected paper distinguishes extraction from update decisions.','The paper and product records describe different memory representations and operating contracts.','The 2025 paper’s update/graph operations cannot be assumed for later OSS or hosted products. Benchmark budgets and representations differ; no present product winner is inferred.','Treat an extracted fact as a versioned interpretation linked to the passage it summarizes.','Test stale facts, contradictions and source recovery rather than only successful recall.','https://arxiv.org/html/2504.19413v1','2025-04-28 v1','{"credit":"Chhikara et al. (2025) and Mem0 maintainers.","evidence":"The paper and product records describe different memory representations and operating contracts.","evidence_basis":"Documented source summary","family":"state","id":"AD-021","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"The 2025 paper’s update/graph operations cannot be assumed for later OSS or hosted products. Benchmark budgets and representations differ; no present product winner is inferred.","mechanism":"Extracts and retrieves persistent information; the inspected paper distinguishes extraction from update decisions.","name":"Mem0","primary_locator":"https://arxiv.org/html/2504.19413v1 — §2.1–2.2; §3.1","primary_url":"https://arxiv.org/html/2504.19413v1","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://arxiv.org/html/2504.19413v1 — §2.1–2.2; §3.1","observed_at":null,"url":"https://arxiv.org/html/2504.19413v1","version":"2025-04-28 v1"},{"locator":null,"observed_at":null,"url":"https://github.com/mem0ai/mem0","version":"cutoff commita39a802bbc93e85b820078cd3c4dbaf53af25dbe"},{"locator":"https://github.com/mem0ai/mem0/releases/tag/v2.0.15 — Bug Fixes Core","observed_at":null,"url":"https://github.com/mem0ai/mem0/releases/tag/v2.0.15","version":"2026-08-01"},{"locator":"https://docs.mem0.ai/migration/oss-v2-to-v3 — Overview, Breaking Changes, Entity collection","observed_at":null,"url":"https://docs.mem0.ai/migration/oss-v2-to-v3","version":"mutable; exact shipment date unresolved"},{"locator":"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/agentic-memory-best-practices.html — lifecycle best practices","observed_at":null,"url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/agentic-memory-best-practices.html","version":"mutable observed after cutoff; precise revision unknown"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/mem0ai/mem0"],"source_version":"2025-04-28 v1","textdata_evaluation":"Test stale facts, contradictions and source recovery rather than only successful recall.","textdata_use":"Treat an extracted fact as a versioned interpretation linked to the passage it summarizes."}');
INSERT INTO "profiles" VALUES('AD-022','Agent Skills','interfaces','Specification and repository','Selected primary text','Packages instructions with optional scripts, references and assets, with progressive loading of detail.','The official format specifies SKILL.md metadata and instructions, with optional scripts, references and assets.','A valid package does not establish methodological correctness or identical client behavior. The allowed-tools field is experimental.','Package method-specific research procedures while retaining their authorship, examples and scope.','Can another researcher use the same procedure and identify its methodological assumptions and boundaries?','https://agentskills.io/specification','Mutable official specification inspected 2026-10-29; no package release tested','{"credit":"Agent Skills specification contributors.","evidence":"The official format specifies SKILL.md metadata and instructions, with optional scripts, references and assets.","evidence_basis":"Selected primary text","family":"interfaces","id":"AD-022","implementation_status":"Not executed or benchmarked for this database.","kind":"Specification and repository","limitations":"A valid package does not establish methodological correctness or identical client behavior. The allowed-tools field is experimental.","mechanism":"Packages instructions with optional scripts, references and assets, with progressive loading of detail.","name":"Agent Skills","primary_locator":"Directory structure; SKILL.md; progressive disclosure","primary_url":"https://agentskills.io/specification","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"Directory structure; SKILL.md; progressive disclosure","observed_at":"2026-10-29","url":"https://agentskills.io/specification","version":"Mutable official specification inspected 2026-10-29; no package release tested"},{"locator":"https://agentskills.io/specification :: #directory-structure; #frontmatter; #compatibility-field; #allowed-tools-field","observed_at":null,"url":"https://agentskills.io/specification","version":"Version not recorded."},{"locator":"https://agentskills.io/client-implementation/adding-skills-support :: #where-to-scan; #handling-name-collisions; #trust-considerations; #filtering; #permission-allowlisting","observed_at":null,"url":"https://agentskills.io/client-implementation/adding-skills-support","version":"Version not recorded."},{"locator":null,"observed_at":null,"url":"https://github.com/agentskills/agentskills","version":"Version not recorded."}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/agentskills/agentskills"],"source_version":"Mutable official specification inspected 2026-10-29; no package release tested","textdata_evaluation":"Can another researcher use the same procedure and identify its methodological assumptions and boundaries?","textdata_use":"Package method-specific research procedures while retaining their authorship, examples and scope."}');
INSERT INTO "profiles" VALUES('AD-023','SWE-agent','interfaces','Paper and repository','Documented source summary','Designs the agent–computer interface around search, a bounded document view, editing and feedback.','The paper’s interface ablations test effects on software-engineering tasks with a specified model.','Coding benchmarks do not validate text interpretation. The need for each interface feature can change with the model.','Make passage inspection and analytic operations easy to invoke and inspect.','Compare a generic tool interface with a task-specific one for missed context and unsupported edits.','https://arxiv.org/html/2405.15793v3','Version not recorded.','{"credit":"Yang et al. (2024).","evidence":"The paper’s interface ablations test effects on software-engineering tasks with a specified model.","evidence_basis":"Documented source summary","family":"interfaces","id":"AD-023","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"Coding benchmarks do not validate text interpretation. The need for each interface feature can change with the model.","mechanism":"Designs the agent–computer interface around search, a bounded document view, editing and feedback.","name":"SWE-agent","primary_locator":"https://arxiv.org/html/2405.15793v3 | Sections 3, 4, 5.1; lines 103-193","primary_url":"https://arxiv.org/html/2405.15793v3","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://arxiv.org/html/2405.15793v3 | Sections 3, 4, 5.1; lines 103-193","observed_at":null,"url":"https://arxiv.org/html/2405.15793v3","version":"Version not recorded."}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/SWE-agent/SWE-agent"],"source_version":"Version not recorded.","textdata_evaluation":"Compare a generic tool interface with a task-specific one for missed context and unsupported edits.","textdata_use":"Make passage inspection and analytic operations easy to invoke and inspect."}');
INSERT INTO "profiles" VALUES('AD-024','Who Validates the Validators / EvalGen','evaluation','Paper and research tool','Documented source summary','Develops evaluators through user inspection and revision of criteria.','The qualitative and empirical study shows that evaluation criteria may change as people inspect outputs.','Matching an earlier rubric does not establish a permanent gold standard. Human inspection itself remains situated and fallible.','Develop task-specific assessment criteria with organizational researchers and retain meaningful revisions.','Do evaluation criteria capture source fidelity and theoretical usefulness, including disputed cases?','https://arxiv.org/html/2404.12272','2024 primary manuscript','{"credit":"Shankar et al. (2024).","evidence":"The qualitative and empirical study shows that evaluation criteria may change as people inspect outputs.","evidence_basis":"Documented source summary","family":"evaluation","id":"AD-024","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and research tool","limitations":"Matching an earlier rubric does not establish a permanent gold standard. Human inspection itself remains situated and fallible.","mechanism":"Develops evaluators through user inspection and revision of criteria.","name":"Who Validates the Validators / EvalGen","primary_locator":"https://arxiv.org/html/2404.12272 — user study and discussion","primary_url":"https://arxiv.org/html/2404.12272","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://arxiv.org/html/2404.12272 — user study and discussion","observed_at":null,"url":"https://arxiv.org/html/2404.12272","version":"2024 primary manuscript"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"2024 primary manuscript","textdata_evaluation":"Do evaluation criteria capture source fidelity and theoretical usefulness, including disputed cases?","textdata_use":"Develop task-specific assessment criteria with organizational researchers and retain meaningful revisions."}');
INSERT INTO "profiles" VALUES('AD-025','Inspect AI','evaluation','Repository and documentation','Selected primary text','Connects evaluation tasks, solvers, scorers and inspectable per-run/per-sample logs.','Official documentation describes log storage, transcript analysis and exported run configuration. Multiple scorers and repeated evaluations are also documented.','The framework executes a chosen evaluation; it does not establish that its scorer measures the intended construct.','Keep an assessment run separate from the workflow under assessment and preserve its configuration and evidence.','Can researchers reproduce the assessed materials and explain why each score was assigned?','https://inspect.aisi.org.uk/eval-logs.html','Mutable official documentation inspected 2026-10-29; no installed version','{"credit":"UK AI Security Institute and Inspect contributors.","evidence":"Official documentation describes log storage, transcript analysis and exported run configuration. Multiple scorers and repeated evaluations are also documented.","evidence_basis":"Selected primary text","family":"evaluation","id":"AD-025","implementation_status":"Not executed or benchmarked for this database.","kind":"Repository and documentation","limitations":"The framework executes a chosen evaluation; it does not establish that its scorer measures the intended construct.","mechanism":"Connects evaluation tasks, solvers, scorers and inspectable per-run/per-sample logs.","name":"Inspect AI","primary_locator":"Overview; Log Format; EvalLog; Exporting Run Config","primary_url":"https://inspect.aisi.org.uk/eval-logs.html","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"Overview; Log Format; EvalLog; Exporting Run Config","observed_at":"2026-10-29","url":"https://inspect.aisi.org.uk/eval-logs.html","version":"Mutable official documentation inspected 2026-10-29; no installed version"},{"locator":null,"observed_at":"2026-07-30T16:17:45Z","url":"https://github.com/UKGovernmentBEIS/inspect_ai","version":"Version not recorded."},{"locator":null,"observed_at":"2026-07-30T16:17:45Z","url":"https://inspect.aisi.org.uk/","version":"Version not recorded."},{"locator":"https://inspect.aisi.org.uk/model-graded.html (Multiple Models and Grading Robustness); https://inspect.aisi.org.uk/metrics.html (Reducing Epochs); https://inspect.aisi.org.uk/eval-logs.html (log schema and export-config)","observed_at":"2026-07-30T16:17:45Z","url":"https://inspect.aisi.org.uk/model-graded.html","version":"Version not recorded."},{"locator":"https://inspect.aisi.org.uk/model-graded.html (Multiple Models and Grading Robustness); https://inspect.aisi.org.uk/metrics.html (Reducing Epochs); https://inspect.aisi.org.uk/eval-logs.html (log schema and export-config)","observed_at":"2026-07-30T16:17:45Z","url":"https://inspect.aisi.org.uk/metrics.html","version":"Version not recorded."},{"locator":"https://inspect.aisi.org.uk/model-graded.html (Multiple Models and Grading Robustness); https://inspect.aisi.org.uk/metrics.html (Reducing Epochs); https://inspect.aisi.org.uk/eval-logs.html (log schema and export-config)","observed_at":"2026-07-30T16:17:45Z","url":"https://inspect.aisi.org.uk/eval-logs.html","version":"Version not recorded."},{"locator":null,"observed_at":"2026-07-30T16:17:45Z","url":"https://inspect.aisi.org.uk/multiple-scorers.html","version":"Version not recorded."}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/UKGovernmentBEIS/inspect_ai"],"source_version":"Mutable official documentation inspected 2026-10-29; no installed version","textdata_evaluation":"Can researchers reproduce the assessed materials and explain why each score was assigned?","textdata_use":"Keep an assessment run separate from the workflow under assessment and preserve its configuration and evidence."}');
INSERT INTO "profiles" VALUES('AD-026','OpenTelemetry GenAI conventions','evidence','Specification and repository','Selected primary text','Defines shared names and relationships for records of model and agent operations.','The official documentation directs readers to a separate repository for GenAI semantic conventions covering model and agent operations.','The former documentation location is no longer maintained. Trace conventions do not supply source-to-claim reasoning or certify complete instrumentation.','Connect model/tool activity records to study evidence while retaining their distinct meanings.','Can an activity log locate the actual source and output artifacts needed to inspect an interpretation?','https://github.com/open-telemetry/semantic-conventions-genai','Official documentation and repository location checked on 29 October 2026; no software release evaluated.','{"credit":"OpenTelemetry contributors.","evidence":"The official documentation directs readers to a separate repository for GenAI semantic conventions covering model and agent operations.","evidence_basis":"Selected primary text","family":"evidence","id":"AD-026","implementation_status":"Not executed or benchmarked for this database.","kind":"Specification and repository","limitations":"The former documentation location is no longer maintained. Trace conventions do not supply source-to-claim reasoning or certify complete instrumentation.","mechanism":"Defines shared names and relationships for records of model and agent operations.","name":"OpenTelemetry GenAI conventions","primary_locator":"Official documentation relocation notice and repository","primary_url":"https://github.com/open-telemetry/semantic-conventions-genai","reading_scope":"The entry draws on selected original text; this does not establish that every referenced work was read in full.","references":[{"locator":"Official documentation relocation notice and repository","observed_at":"2026-10-29","url":"https://github.com/open-telemetry/semantic-conventions-genai","version":"Repository identity; documentation relocation checked 2026-10-29"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/open-telemetry/semantic-conventions-genai"],"source_version":"Official documentation and repository location checked on 29 October 2026; no software release evaluated.","textdata_evaluation":"Can an activity log locate the actual source and output artifacts needed to inspect an interpretation?","textdata_use":"Connect model/tool activity records to study evidence while retaining their distinct meanings."}');
INSERT INTO "profiles" VALUES('AD-027','AgentDojo','evidence','Benchmark and repository','Documented source summary','Combines legitimate tool tasks with attacks through untrusted content and evaluates utility and attack outcomes.','The primary project documentation describes a dynamic evaluation environment with task suites, attacks and defenses.','Benchmark outcomes depend on attack access, tasks and defenses. No deployment-specific risk rate or complete defense follows.','Keep retrieved text as evidence rather than allowing embedded instructions to silently redirect an inquiry.','Can an agent use a source passage while rejecting unrelated instructions carried in that passage?','https://agentdojo.spylab.ai/','Version not recorded.','{"credit":"AgentDojo authors and ETH Zürich SPY Lab contributors.","evidence":"The primary project documentation describes a dynamic evaluation environment with task suites, attacks and defenses.","evidence_basis":"Documented source summary","family":"evidence","id":"AD-027","implementation_status":"Not executed or benchmarked for this database.","kind":"Benchmark and repository","limitations":"Benchmark outcomes depend on attack access, tasks and defenses. No deployment-specific risk rate or complete defense follows.","mechanism":"Combines legitimate tool tasks with attacks through untrusted content and evaluates utility and attack outcomes.","name":"AgentDojo","primary_locator":"Project homepage, overview paragraphs and documentation links for tasks, attacks, and defenses","primary_url":"https://agentdojo.spylab.ai/","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":null,"observed_at":"2026-07-31T05:05:00Z","url":"https://agentdojo.spylab.ai/","version":"Version not recorded."},{"locator":null,"observed_at":"2026-07-31T05:06:00Z","url":"https://github.com/ethz-spylab/agentdojo","version":"Version not recorded."}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/ethz-spylab/agentdojo"],"source_version":"Version not recorded.","textdata_evaluation":"Can an agent use a source passage while rejecting unrelated instructions carried in that passage?","textdata_use":"Keep retrieved text as evidence rather than allowing embedded instructions to silently redirect an inquiry."}');
INSERT INTO "profiles" VALUES('AD-028','PrivacyLens','evidence','Benchmark paper','Documented source summary','Examines privacy-relevant behavior in agent actions as well as responses about privacy norms.','The paper reports a distinction between stated privacy judgments and information exposed during actions.','Its tasks and leakage definitions bound the result; probing a norm and observing an action are different measurements.','Assess how a research workflow handles sensitive contextual information during tool use and output preparation.','Does the actual exported analysis respect the study’s authorized source and participant boundaries?','https://arxiv.org/html/2409.00138v3','2025-03-14 v3; NeurIPS 2024','{"credit":"Shao et al.; NeurIPS 2024 identity, inspected arXiv v3 (2025).","evidence":"The paper reports a distinction between stated privacy judgments and information exposed during actions.","evidence_basis":"Documented source summary","family":"evidence","id":"AD-028","implementation_status":"Not executed or benchmarked for this database.","kind":"Benchmark paper","limitations":"Its tasks and leakage definitions bound the result; probing a norm and observing an action are different measurements.","mechanism":"Examines privacy-relevant behavior in agent actions as well as responses about privacy norms.","name":"PrivacyLens","primary_locator":"https://arxiv.org/html/2409.00138v3 §3–6, Table 2","primary_url":"https://arxiv.org/html/2409.00138v3","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://arxiv.org/html/2409.00138v3 §3–6, Table 2","observed_at":"2026-09-20T17:53:16.634879+00:00","url":"https://arxiv.org/html/2409.00138v3","version":"2025-03-14 v3; NeurIPS 2024"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"2025-03-14 v3; NeurIPS 2024","textdata_evaluation":"Does the actual exported analysis respect the study’s authorized source and participant boundaries?","textdata_use":"Assess how a research workflow handles sensitive contextual information during tool use and output preparation."}');
INSERT INTO "profiles" VALUES('AD-029','Berkeley Function Calling Leaderboard','evaluation','Benchmark and documentation','Documented source summary','Assesses function calling, including state and viable call sequences in multi-turn tasks.','The official articles distinguish evaluation categories and requirements beyond well-formed syntax.','The documented article weights and live aggregates differ. Historical versions do not establish a single current model ranking.','Assess whether a requested analytic operation is selected and parameterized correctly.','Distinguish a valid call, a correct state transition and a substantively appropriate research operation.','https://gorilla.cs.berkeley.edu/blogs/15_bfcl_v4_web_search.html','V4 explanatory article; not the live scorer commit','{"credit":"Berkeley Function Calling Leaderboard authors and maintainers.","evidence":"The official articles distinguish evaluation categories and requirements beyond well-formed syntax.","evidence_basis":"Documented source summary","family":"evaluation","id":"AD-029","implementation_status":"Not executed or benchmarked for this database.","kind":"Benchmark and documentation","limitations":"The documented article weights and live aggregates differ. Historical versions do not establish a single current model ranking.","mechanism":"Assesses function calling, including state and viable call sequences in multi-turn tasks.","name":"Berkeley Function Calling Leaderboard","primary_locator":"Full Leaderboard Score Composition table; dataset counts","primary_url":"https://gorilla.cs.berkeley.edu/blogs/15_bfcl_v4_web_search.html","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":null,"observed_at":null,"url":"https://gorilla.cs.berkeley.edu/blogs/15_bfcl_v4_web_search.html","version":"V4 explanatory article; not the live scorer commit"},{"locator":null,"observed_at":null,"url":"https://gorilla.cs.berkeley.edu/blogs/13_bfcl_v3_multi_turn.html","version":"V3 multi-turn explanatory article"},{"locator":null,"observed_at":null,"url":"https://gorilla.cs.berkeley.edu/leaderboard.html","version":"live page says last updated 2026-04-12; bfcl-eval2025.12.17, commit f7cf735"},{"locator":null,"observed_at":null,"url":"https://www2.eecs.berkeley.edu/Pubs/TechRpts/2025/Archive/EECS-2025-184.pdf","version":"Fanjia Yan, A Function Calling Perspective on Scalable Large Language Model Agent Evaluation; UCB/EECS-2025-184 May14 2025 cover, inner copyright2026/2025 mismatch; not asserted identical to ICML paper"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"V4 explanatory article; not the live scorer commit","textdata_evaluation":"Distinguish a valid call, a correct state transition and a substantively appropriate research operation.","textdata_use":"Assess whether a requested analytic operation is selected and parameterized correctly."}');
INSERT INTO "profiles" VALUES('AD-030','tau-bench','evaluation','Benchmark paper','Documented source summary','Evaluates repeated success in stateful, policy-bearing interactions among a user simulator, agent and tools.','The paper distinguishes succeeding on every repeated attempt (pass^k) from finding at least one successful attempt.','Final-state equality can miss process violations and simulated-user errors can affect results. Historical scores are not present capability estimates.','Measure reliability across repeated research tasks while also inspecting process and evidence quality.','Does an arrangement repeatedly retain the same study commitments without hiding substantively different errors?','https://arxiv.org/html/2406.12045v1','v1 June2024','{"credit":"Yao et al. (2024).","evidence":"The paper distinguishes succeeding on every repeated attempt (pass^k) from finding at least one successful attempt.","evidence_basis":"Documented source summary","family":"evaluation","id":"AD-030","implementation_status":"Not executed or benchmarked for this database.","kind":"Benchmark paper","limitations":"Final-state equality can miss process violations and simulated-user errors can affect results. Historical scores are not present capability estimates.","mechanism":"Evaluates repeated success in stateful, policy-bearing interactions among a user simulator, agent and tools.","name":"tau-bench","primary_locator":"https://arxiv.org/html/2406.12045v1#S5","primary_url":"https://arxiv.org/html/2406.12045v1","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":null,"observed_at":null,"url":"https://arxiv.org/html/2406.12045v1","version":"v1 June2024"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"v1 June2024","textdata_evaluation":"Does an arrangement repeatedly retain the same study commitments without hiding substantively different errors?","textdata_use":"Measure reliability across repeated research tasks while also inspecting process and evidence quality."}');
INSERT INTO "profiles" VALUES('AD-031','GEPA','evaluation','Paper and repository','Documented source summary','Uses execution feedback to reflect on and evolve prompts while selecting among candidate trade-offs.','The conference paper keeps task-model weights fixed and evaluates prompt evolution across several benchmarks.','Advantages vary by task; optimization exposure and evaluation selection matter. Bounded transfer evidence does not imply future-model invariance.','Explore revisions to reusable prompts while keeping evaluation materials and prior variants traceable.','Does an optimized prompt improve held-out source fidelity without sacrificing another required criterion?','https://proceedings.iclr.cc/paper_files/paper/2026/file/0e9e708b6f48e14fd0ac29e167413f76-Paper-Conference.pdf','conference version of record','{"credit":"Agrawal et al. (2026 conference version) and GEPA contributors.","evidence":"The conference paper keeps task-model weights fixed and evaluates prompt evolution across several benchmarks.","evidence_basis":"Documented source summary","family":"evaluation","id":"AD-031","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and repository","limitations":"Advantages vary by task; optimization exposure and evaluation selection matter. Bounded transfer evidence does not imply future-model invariance.","mechanism":"Uses execution feedback to reflect on and evolve prompts while selecting among candidate trade-offs.","name":"GEPA","primary_locator":"https://proceedings.iclr.cc/paper_files/paper/2026/file/0e9e708b6f48e14fd0ac29e167413f76-Paper-Conference.pdf#page=6","primary_url":"https://proceedings.iclr.cc/paper_files/paper/2026/file/0e9e708b6f48e14fd0ac29e167413f76-Paper-Conference.pdf","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":null,"observed_at":null,"url":"https://proceedings.iclr.cc/paper_files/paper/2026/file/0e9e708b6f48e14fd0ac29e167413f76-Paper-Conference.pdf","version":"conference version of record"},{"locator":"https://github.com/gepa-ai/gepa/releases/tag/v0.1.4","observed_at":null,"url":"https://github.com/gepa-ai/gepa/releases/tag/v0.1.4","version":"v0.1.4 / short commit 8b0ce6c"},{"locator":"https://github.com/gepa-ai/gepa/blob/v0.1.4/LICENSE","observed_at":null,"url":"https://github.com/gepa-ai/gepa/blob/v0.1.4/LICENSE","version":"tag-scoped MIT text"},{"locator":null,"observed_at":null,"url":"https://github.com/gepa-ai/gepa/issues/379","version":"open when inspected"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/gepa-ai/gepa"],"source_version":"conference version of record","textdata_evaluation":"Does an optimized prompt improve held-out source fidelity without sacrificing another required criterion?","textdata_use":"Explore revisions to reusable prompts while keeping evaluation materials and prior variants traceable."}');
INSERT INTO "profiles" VALUES('AD-032','MIPRO and MIPROv2','evaluation','Paper and implementation','Documented source summary','Optimizes module-level instructions and demonstrations against downstream task scores.','The paper studies multi-stage language-model programs; current MIPROv2 documentation is a distinct software manifestation.','Results depend on the program, metric and data split; two small paper tasks lack a separate development split. Paper and current API are not interchangeable evidence.','Keep prompt optimization data separate from held-out assessment of a measurement procedure.','Compare optimized and manually specified procedures on untouched organizational texts and inspect retained examples.','https://arxiv.org/html/2406.11695v2','v2; EMNLP 2024 relation in arXiv metadata','{"credit":"Opsahl-Ong et al. (2024) and DSPy contributors.","evidence":"The paper studies multi-stage language-model programs; current MIPROv2 documentation is a distinct software manifestation.","evidence_basis":"Documented source summary","family":"evaluation","id":"AD-032","implementation_status":"Not executed or benchmarked for this database.","kind":"Paper and implementation","limitations":"Results depend on the program, metric and data split; two small paper tasks lack a separate development split. Paper and current API are not interchangeable evidence.","mechanism":"Optimizes module-level instructions and demonstrations against downstream task scores.","name":"MIPRO and MIPROv2","primary_locator":"https://arxiv.org/html/2406.11695v2#S4.SS3","primary_url":"https://arxiv.org/html/2406.11695v2","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":null,"observed_at":null,"url":"https://arxiv.org/html/2406.11695v2","version":"v2; EMNLP 2024 relation in arXiv metadata"},{"locator":null,"observed_at":null,"url":"https://dspy.ai/api/optimizers/MIPROv2/","version":"mutable API documentation"},{"locator":null,"observed_at":null,"url":"https://github.com/stanfordnlp/dspy/issues/9308","version":"DSPy3.1.3; closed"},{"locator":null,"observed_at":null,"url":"https://github.com/stanfordnlp/dspy/issues/9039","version":"DSPy3.0.3; closed"},{"locator":"https://aclanthology.org/2024.emnlp-main.525/ ; Title/authors, venue, date, pages and DOI","observed_at":"2026-09-15T01:34:18+00:00","url":"https://aclanthology.org/2024.emnlp-main.525/","version":"EMNLP 2024 VOR, pp. 9340–9366"},{"locator":"https://aclanthology.org/2024.emnlp-main.525.pdf ; Appendix B.1 and Table 3, PDF pp.13–14 (printed pp.9352–9353)","observed_at":"2026-09-15T01:34:18+00:00","url":"https://aclanthology.org/2024.emnlp-main.525.pdf","version":"EMNLP 2024 VOR, pp. 9340–9366"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":["https://github.com/stanfordnlp/dspy"],"source_version":"v2; EMNLP 2024 relation in arXiv metadata","textdata_evaluation":"Compare optimized and manually specified procedures on untouched organizational texts and inspect retained examples.","textdata_use":"Keep prompt optimization data separate from held-out assessment of a measurement procedure."}');
INSERT INTO "profiles" VALUES('AD-033','AI Agents That Matter','evaluation','Evaluation paper','Documented source summary','Frames agent assessment jointly in terms of task accuracy, cost and intended generality.','The paper distinguishes development expenditure from per-use inference and discusses holdouts appropriate to intended use.','These evaluation principles do not certify that a particular benchmark captures organizational research quality.','Assess scholarly output alongside model calls, elapsed time and researcher effort.','Does a more elaborate arrangement improve the intended research outcome under a meaningful resource comparison?','https://arxiv.org/html/2407.01502v1','v1 July2024; later manifestations not used for claims','{"credit":"Kapoor et al. (2024); inspected arXiv v1.","evidence":"The paper distinguishes development expenditure from per-use inference and discusses holdouts appropriate to intended use.","evidence_basis":"Documented source summary","family":"evaluation","id":"AD-033","implementation_status":"Not executed or benchmarked for this database.","kind":"Evaluation paper","limitations":"These evaluation principles do not certify that a particular benchmark captures organizational research quality.","mechanism":"Frames agent assessment jointly in terms of task accuracy, cost and intended generality.","name":"AI Agents That Matter","primary_locator":"https://arxiv.org/html/2407.01502v1 ; §3 fixed/variablecost;§4 downstream evaluation;§5 holdoutgenerality","primary_url":"https://arxiv.org/html/2407.01502v1","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://arxiv.org/html/2407.01502v1 ; §3 fixed/variablecost;§4 downstream evaluation;§5 holdoutgenerality","observed_at":null,"url":"https://arxiv.org/html/2407.01502v1","version":"v1 July2024; later manifestations not used for claims"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"v1 July2024; later manifestations not used for claims","textdata_evaluation":"Does a more elaborate arrangement improve the intended research outcome under a meaningful resource comparison?","textdata_use":"Assess scholarly output alongside model calls, elapsed time and researcher effort."}');
INSERT INTO "profiles" VALUES('AD-034','Handoff Debt','coordination','Empirical paper','Documented source summary','Compares repository-only, raw-trace, summary and structured-note views at frozen worker-takeover points.','The v2 study uses software tasks and successor models to test how inherited context affects continuation.','Resolution gains vary; note-generation costs and execution context qualify the comparison. No note format is uniformly best, and the task is software continuation.','Pass the question, source references, completed work and unresolved interpretations to a successor researcher or agent.','Can a successor recover both the result and the reason a competing interpretation remained open?','https://arxiv.org/html/2606.02875v2','arXiv 2606.02875 v2, 2026-08-30.','{"credit":"Handoff Debt authors as identified in the linked primary paper.","evidence":"The v2 study uses software tasks and successor models to test how inherited context affects continuation.","evidence_basis":"Documented source summary","family":"coordination","id":"AD-034","implementation_status":"Not executed or benchmarked for this database.","kind":"Empirical paper","limitations":"Resolution gains vary; note-generation costs and execution context qualify the comparison. No note format is uniformly best, and the task is software continuation.","mechanism":"Compares repository-only, raw-trace, summary and structured-note views at frozen worker-takeover points.","name":"Handoff Debt","primary_locator":"https://arxiv.org/html/2606.02875 §3–6 Tables2–4; Limitations","primary_url":"https://arxiv.org/html/2606.02875v2","reading_scope":"The entry draws on a documented source summary. A full-text review is not established for this entry.","references":[{"locator":"https://arxiv.org/html/2606.02875 §3–6 Tables2–4; Limitations","observed_at":null,"url":"https://arxiv.org/html/2606.02875","version":"v2 2026-08-30"}],"repository_status":"Link for inspection; no installation, license clearance or latest-release claim","repository_urls":[],"source_version":"arXiv 2606.02875 v2, 2026-08-30.","textdata_evaluation":"Can a successor recover both the result and the reason a competing interpretation remained open?","textdata_use":"Pass the question, source references, completed work and unresolved interpretations to a successor researcher or agent."}');
